<?php
 namespace QQWorld\Config\Controller\Adminhtml\System\Config; use QQWorld\Config\Controller\Adminhtml\System\ConfigSectionChecker; abstract class AbstractScopeConfig extends \QQWorld\Config\Controller\Adminhtml\System\AbstractConfig { protected $_backendConfig; public function __construct( \QQWorld\Backend\App\Action\Context $context, \QQWorld\Config\Model\Config\Structure $configStructure, ConfigSectionChecker $sectionChecker, \QQWorld\Config\Model\Config $backendConfig ) { $this->_backendConfig = $backendConfig; parent::__construct($context, $configStructure, $sectionChecker); } protected function isSectionAllowed($sectionId) { $website = $this->getRequest()->getParam('website'); $store = $this->getRequest()->getParam('store'); if ($store) { $this->_backendConfig->setStore($store); } elseif ($website) { $this->_backendConfig->setWebsite($website); } return parent::isSectionAllowed($sectionId); } } 